// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.model;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.sail.lmdb.ValueStore;
import org.eclipse.rdf4j.sail.lmdb.ValueStoreRevision;
import org.eclipse.rdf4j.sail.lmdb.inlined.Values;
import org.junit.jupiter.api.Test;

/**
 * Every inlined literal id encodes its (XSD core) datatype in the id's type bits, so asking a lazy {@link LmdbLiteral}
 * for its datatype or core datatype must never resolve the value.
 */
class LmdbLiteralInlinedCoreDatatypeTest {

	private final ValueFactory vf = SimpleValueFactory.getInstance();

	/**
	 * A revision that fails the test as soon as a value resolution is attempted.
	 */
	private static final class NonResolvingRevision implements ValueStoreRevision {

		@Override
		public long getRevisionId() {
			return 42;
		}

		@Override
		public ValueStore getValueStore() {
			return null;
		}

		@Override
		public boolean resolveValue(long id, LmdbValue value) {
			throw new AssertionError(
					"datatype of an inlined literal id must be derived from the id without resolving, id=" + id);
		}
	}

	private final List<Literal> literals = Arrays.asList(
			vf.createLiteral(new BigDecimal("123456789.987654321")),
			vf.createLiteral(3.14159d),
			vf.createLiteral(1.5f),
			vf.createLiteral(BigInteger.valueOf(-12345)),
			vf.createLiteral(123456789L),
			vf.createLiteral(42),
			vf.createLiteral((short) 999),
			vf.createLiteral((byte) 42),
			vf.createLiteral("123456789", XSD.UNSIGNED_LONG),
			vf.createLiteral("123456", XSD.UNSIGNED_INT),
			vf.createLiteral("12345", XSD.UNSIGNED_SHORT),
			vf.createLiteral("42", XSD.UNSIGNED_BYTE),
			vf.createLiteral("42", XSD.POSITIVE_INTEGER),
			vf.createLiteral("-42", XSD.NEGATIVE_INTEGER),
			vf.createLiteral("123", XSD.NON_NEGATIVE_INTEGER),
			vf.createLiteral("-99", XSD.NON_POSITIVE_INTEGER),
			vf.createLiteral("RDF4J", XSD.STRING),
			vf.createLiteral(LocalDateTime.of(2020, 2, 29, 12, 0, 0)),
			vf.createLiteral(OffsetDateTime.of(2020, 2, 29, 12, 0, 0, 0, ZoneOffset.UTC)),
			vf.createLiteral(LocalDate.of(2024, 6, 13)),
			vf.createLiteral(true),
			vf.createLiteral(false));

	@Test
	void coreDatatypeOfInlinedIdNeverResolvesValue() {
		int inlinedCount = 0;
		for (Literal literal : literals) {
			for (boolean orderedNumericIds : new boolean[] { false, true }) {
				long packed = Values.packLiteral(literal, orderedNumericIds);
				if (packed == 0L) {
					continue;
				}
				inlinedCount++;

				LmdbLiteral lazy = new LmdbLiteral(new NonResolvingRevision(), packed);
				assertEquals(literal.getCoreDatatype(), lazy.getCoreDatatype(),
						"core datatype for " + literal + " (ordered=" + orderedNumericIds + ")");
				assertEquals(literal.getDatatype(), lazy.getDatatype(),
						"datatype for " + literal + " (ordered=" + orderedNumericIds + ")");
			}
		}
		assertTrue(inlinedCount >= 30, "expected the fixture to exercise the inlined id space, saw " + inlinedCount);
	}
}
